import json,random,time

def lookup(encoded,engine):
    time.sleep(random.uniform(0.018,0.024))
    if engine=='direct':
        records=json.loads(encoded)
    elif engine=='buffered':
        records=json.loads(encoded.encode('utf-8').decode('utf-8'))
    else:
        raise ValueError(engine)
    return {'items':[r for r in records if r['enabled']],'completed':len(records),'errors':0}
